import {
  Box,
} from "@mui/material";

import WeatherIntelligence from "./WeatherIntelligence";
import ForecastStatistics from "./ForecastStatistics";
import ForecastTrendChart from "./ForecastTrendChart";
import ScenarioTrendChart from "./ScenarioTrendChart";
import StockpileTrajectory from "./StockpileTrajectory";
import ForecastInsights from "./ForecastInsights";
import ScenarioComparison from "./ScenarioComparison";
import WeatherCorrelation from "./WeatherCorrelation";

import {
  useForecastContext,
} from "../../../contexts/ForecastContext";

import {
  ForecastFilters,
} from "../types/forecast.types";


const ForecastOverview = () => {

  const {
    horizon,
    metric,
    entityId,
    scenario,
  } = useForecastContext();


  const filters:
    ForecastFilters = {
      horizon,
      metric,
      entityId,
      scenario,
    };


  return (
    <Box
      sx={{
        width: "100%",
        minWidth: 0,
      }}
    >

      {/* ==================================================
          FORECAST STATISTICS
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,

          mb: {
            xs: 2.5,
            md: 3,
          },
        }}
      >
        <ForecastStatistics />
      </Box>


      {/* ==================================================
          WEATHER INTELLIGENCE
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,

          mb: {
            xs: 2.5,
            md: 3,
          },
        }}
      >
        <WeatherIntelligence
          entityId={entityId}
        />
      </Box>


      {/* ==================================================
          WEATHER CORRELATION
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,

          mb: {
            xs: 2.5,
            md: 3,
          },
        }}
      >
        <WeatherCorrelation
          filters={filters}
        />
      </Box>


      {/* ==================================================
          FORECAST TREND + SCENARIO COMPARISON
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,

          display: "grid",

          gridTemplateColumns: {
            xs:
              "minmax(0, 1fr)",

            xl:
              "minmax(0, 1.5fr) minmax(0, 1fr)",
          },

          gap: {
            xs: 2.5,
            md: 3,
          },

          alignItems:
            "stretch",

          mb: {
            xs: 2.5,
            md: 3,
          },

          "& > *": {
            minWidth: 0,
          },
        }}
      >

        {/* ==================================================
            MAIN BURN + SUPPLY CHART
        ================================================== */}

        <Box
          sx={{
            width: "100%",
            minWidth: 0,
          }}
        >
          <ForecastTrendChart
            filters={filters}
          />
        </Box>


        {/* ==================================================
            COMPACT SCENARIO COMPARISON
        ================================================== */}

        <Box
          sx={{
            width: "100%",
            minWidth: 0,
          }}
        >
          <ScenarioComparison
            filters={filters}
          />
        </Box>

      </Box>


      {/* ==================================================
          DETAILED SCENARIO TREND
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,

          mb: {
            xs: 2.5,
            md: 3,
          },

          "& > *": {
            width: "100%",
            minWidth: 0,
          },
        }}
      >
        <ScenarioTrendChart
          filters={filters}
        />
      </Box>


      {/* ==================================================
          STOCKPILE + INSIGHTS
      ================================================== */}

      <Box
        sx={{
          width: "100%",
          minWidth: 0,

          display: "grid",

          gridTemplateColumns: {
            xs:
              "minmax(0, 1fr)",

            xl:
              "minmax(0, 1.35fr) minmax(0, 1fr)",
          },

          gap: {
            xs: 2.5,
            md: 3,
          },

          alignItems:
            "stretch",

          mb: {
            xs: 2.5,
            md: 3,
          },

          "& > *": {
            minWidth: 0,
          },
        }}
      >

        {/* STOCKPILE */}

        <Box
          sx={{
            minWidth: 0,
            width: "100%",
          }}
        >
          <StockpileTrajectory
            filters={filters}
          />
        </Box>


        {/* INSIGHTS */}

        <Box
          sx={{
            minWidth: 0,
            width: "100%",
          }}
        >
          <ForecastInsights
            filters={filters}
          />
        </Box>

      </Box>

    </Box>
  );
};


export default ForecastOverview;
